    <div class="container">
        <!-- Les Boutons / Onglets -->
        <div class="tabs-header">
            <button class="tab-btn active" onclick="openPage(event, 'page1')">Accueil</button>
            <button class="tab-btn" onclick="openPage(event, 'page2')">Services</button>
            <button class="tab-btn" onclick="openPage(event, 'page3')">Contact</button>
        </div>

        <!-- Les Contenus / Pages -->
        <div class="tabs-content">
            <!-- Page 1 -->
            <div id="page1" class="tab-pane active">
                <h2>Page d'Accueil</h2>
                <p>Bienvenue sur la mission #25. Ceci est le contenu de la page d'accueil qui s'affiche lorsque vous cliquez sur l'onglet correspondant.</p>
            </div>

