        .search-group input, .search-group select {
            padding: 0.75rem;
            border: 1px solid var(--gray-light);
            border-radius: 8px;
            background-color: var(--neutral-light);
            color: var(--neutral-dark);
        }

        /* =================================================================
           7. DESTINATIONS & FILTRAGE CSS PUR
           ================================================================ */
        .destinations {
            background-color: var(--neutral-light);
        }

        /* Logique de filtrage par boutons radio cachés */
        .filter-input {
            display: none;
        }

        .filter-buttons {
            display: flex;
            justify-content: center;
            gap: 1rem;
            margin-bottom: 3rem;
            flex-wrap: wrap;
