            padding: 8rem 0;
        }

        /* Logique des filtres par boutons radio */
        .filters {
            display: flex;
            justify-content: center;
            gap: 1rem;
            margin-bottom: 4rem;
            flex-wrap: wrap;
        }

        .filters input[type="radio"] {
            display: none;
        }

        .filter-btn {
            padding: 0.6rem 1.5rem;
            border: 1px solid var(--border-gold);
            color: var(--color-muted);
            cursor: pointer;
            font-size: 0.8rem;
            text-transform: uppercase;
            letter-spacing: 0.15em;
            transition: var(--transition-smooth);
            background: var(--bg-surface);
        }

        .filter-btn:hover {
            border-color: var(--gold);
            color: var(--color-ivory);
        }

        #filter-all:checked ~ .filters label[for="filter-all"],
        #filter-europe:checked ~ .filters label[for="filter-europe"],
        #filter-asia:checked ~ .filters label[for="filter-asia"],
        #filter-americas:checked ~ .filters label[for="filter-americas"] {
            background-color: var(--gold);
            color: var(--bg-deep);
            border-color: var(--gold);
        }

        /* Grille des cartes et filtrage dynamique CSS */
        .destinations-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
            gap: 2.5rem;
        }

        .destination-card {
            background-color: var(--bg-card);
            border: 1px solid var(--border-gold);
            overflow: hidden;
            transition: var(--transition-smooth);
            display: flex;
            flex-direction: column;
        }

        .destination-card:hover {
            transform: translateY(-8px);
            box-shadow: 0 15px 30px rgba(212, 175, 55, 0.1);
        }

        .card-img-wrapper {
            position: relative;
            height: 280px;
            overflow: hidden;
            background: linear-gradient(45deg, #1a1d24, #2a2e39); /* Fond de secours */
        }

        .card-img-wrapper img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
        }

        .destination-card:hover .card-img-wrapper img {
            transform: scale(1.05);
        }

        .card-content {
            padding: 2rem;
            display: flex;
            flex-direction: column;
            flex-grow: 1;
            justify-content: space-between;
        }

        .card-location {
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.2em;
            color: var(--gold);
            margin-bottom: 0.5rem;
        }

        .card-title {
            font-size: 1.5rem;
            margin-bottom: 1rem;
        }

        .card-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-top: 1px solid rgba(255,255,255,0.05);
            padding-top: 1rem;
            margin-top: 1rem;
            font-size: 0.9rem;
            color: var(--color-muted);
        }

        .card-price span {
            color: var(--color-ivory);
            font-family: var(--font-serif);
            font-size: 1.2rem;
        }

        /* Filtrage masquage/affichage via les radio buttons */
        #filter-europe:checked ~ .destinations-grid .card:not(.europe),
        #filter-asia:checked ~ .destinations-grid .card:not(.asia),
        #filter-americas:checked ~ .destinations-grid .card:not(.americas) {
            display: none;
        }

        /* =================================================================
           6. OFFRES EXCLUSIVES
           ================================================================ */
        .offers-section {
            padding: 8rem 0;
            background-color: var(--bg-surface);
            border-top: 1px solid var(--border-gold);
            border-bottom: 1px solid var(--border-gold);
        }

        .offers-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
            gap: 2.5rem;
        }

        .offer-card {
            background-color: var(--bg-deep);
            border: 1px solid var(--border-gold);
            padding: 3rem 2rem;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            position: relative;
        }

        .offer-badge {
            position: absolute;
            top: 1.5rem;
            right: 1.5rem;
            background: rgba(212, 175, 55, 0.1);
            color: var(--gold);
            border: 1px solid var(--border-gold);
            padding: 0.25rem 0.75rem;
            font-size: 0.7rem;
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        .offer-title {
            font-size: 1.75rem;
            margin-bottom: 1rem;
        }

        .offer-duration {
            color: var(--gold);
            font-size: 0.85rem;
            text-transform: uppercase;
            letter-spacing: 0.15em;
            margin-bottom: 1.5rem;
        }

        .offer-features {
            list-style: none;
            margin-bottom: 2.5rem;
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
            color: var(--color-muted);
            font-size: 0.95rem;
        }

        .offer-features li::before {
            content: "— ";
            color: var(--gold);
        }

        .offer-bottom {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-top: 1px solid rgba(255,255,255,0.05);
            padding-top: 1.5rem;
        }

        .offer-price {
            font-size: 1.5rem;
            font-family: var(--font-serif);
            color: var(--color-ivory);
        }

        /* =================================================================
           7. POURQUOI NOUS CHOISIR (AVANTAGES SVG)
           ================================================================ */
        .features-section {
            padding: 8rem 0;
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 3rem;
        }

        .feature-box {
            text-align: center;
            padding: 2.5rem 1.5rem;
            background: var(--bg-card);
            border: 1px solid var(--border-gold);
            transition: var(--transition-smooth);
        }

        .feature-box:hover {
            transform: translateY(-5px);
            border-color: var(--gold);
        }

        .feature-icon {
            width: 48px;
            height: 48px;
            margin: 0 auto 1.5rem auto;
            stroke: var(--gold);
            fill: none;
            stroke-width: 1.5;
        }

        .feature-title {
            font-size: 1.25rem;
            margin-bottom: 1rem;
        }

        .feature-desc {
            color: var(--color-muted);
            font-size: 0.9rem;
        }

        /* =================================================================
           8. À PROPOS & CHIFFRES CLÉS
           ================================================================ */
        .about-section {
            padding: 8rem 0;
            background-color: var(--bg-surface);
        }

        .about-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 4rem;
            align-items: center;
            margin-bottom: 6rem;
        }

        @media (max-width: 900px) {
            .about-grid {
                grid-template-columns: 1fr;
            }
        }

        .about-text h3 {
            font-size: 2.5rem;
            margin-bottom: 1.5rem;
        }

        .about-text p {
            color: var(--color-muted);
            margin-bottom: 1.5rem;
        }

        .about-img-wrapper {
            position: relative;
            height: 450px;
            background: linear-gradient(45deg, #1a1d24, #2a2e39);
        }

        .about-img-wrapper img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            border: 1px solid var(--border-gold);
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 2rem;
            text-align: center;
            border-top: 1px solid var(--border-gold);
            border-bottom: 1px solid var(--border-gold);
            padding: 4rem 0;
        }

        .stat-item h4 {
            font-size: 3.5rem;
            color: var(--gold);
            font-family: var(--font-serif);
            margin-bottom: 0.5rem;
        }

        .stat-item p {
            font-size: 0.85rem;
            text-transform: uppercase;
            letter-spacing: 0.2em;
            color: var(--color-muted);
        }

        /* Équipe */
        .team-heading {
            text-align: center;
            margin: 6rem 0 3rem 0;
            font-size: 2rem;
        }

        .team-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 2rem;
        }

        .team-member {
            background: var(--bg-deep);
            border: 1px solid var(--border-gold);
            text-align: center;
            padding-bottom: 2rem;
            overflow: hidden;
        }

        .team-img {
            height: 300px;
            background: linear-gradient(45deg, #1a1d24, #2a2e39);
            margin-bottom: 1.5rem;
        }

        .team-img img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .team-member h5 {
            font-size: 1.25rem;
            margin-bottom: 0.25rem;
        }

        .team-member p {
            color: var(--gold);
            font-size: 0.85rem;
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        /* =================================================================
           9. TÉMOIGNAGES & FAQ
           ================================================================ */
        .testimonials-section {
            padding: 8rem 0;
        }

        .testimonials-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
            gap: 2.5rem;
            margin-bottom: 8rem;
        }

        .testimonial-card {
            background: var(--bg-card);
            border: 1px solid var(--border-gold);
            padding: 3rem;
            position: relative;
        }

        .testimonial-card::before {
            content: "“";
            position: absolute;
            top: 1rem;
            left: 2rem;
            font-size: 6rem;
            font-family: var(--font-serif);
            color: var(--gold);
            opacity: 0.2;
            line-height: 1;
        }

        .testimonial-text {
            color: var(--color-muted);
            font-style: italic;
            margin-bottom: 2rem;
            position: relative;
            z-index: 1;
        }

        .testimonial-author {
            display: flex;
            align-items: center;
            gap: 1rem;
        }

        .author-avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            overflow: hidden;
            background: linear-gradient(45deg, #1a1d24, #2a2e39);
        }

        .author-avatar img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .author-info h6 {
            font-size: 1rem;
        }

        .author-info span {
            font-size: 0.75rem;
            color: var(--gold);
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        /* FAQ Accordéon natif */
        .faq-container {
            max-width: 900px;
            margin: 0 auto;
        }

        .faq-title {
            text-align: center;
            font-size: 2rem;
            margin-bottom: 3rem;
        }

        details {
            background: var(--bg-card);
            border: 1px solid var(--border-gold);
            margin-bottom: 1rem;
            transition: var(--transition-smooth);
        }

        details[open] {
            border-color: var(--gold);
        }

        summary {
            padding: 1.5rem 2rem;
            font-size: 1.1rem;
            cursor: pointer;
            list-style: none;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-family: var(--font-serif);
        }

        summary::-webkit-details-marker {
            display: none;
        }

        summary::after {
            content: "+";
            font-size: 1.5rem;
            color: var(--gold);
            transition: transform 0.3s ease;
        }

        details[open] summary::after {
            transform: rotate(45deg);
        }

        .faq-content {
            padding: 0 2rem 1.5rem 2rem;
            color: var(--color-muted);
            font-size: 0.95rem;
            border-top: 1px solid rgba(255,255,255,0.05);
            padding-top: 1.5rem;
        }

        /* =================================================================
           10. CONTACT & FORMULAIRE
           ================================================================ */
        .contact-section {
            padding: 8rem 0;
            background-color: var(--bg-surface);
            border-top: 1px solid var(--border-gold);
        }

        .contact-grid {
            display: grid;
            grid-template-columns: 1fr 1.5fr;
            gap: 4rem;
        }

        @media (max-width: 900px) {
            .contact-grid {
                grid-template-columns: 1fr;
            }
        }

        .contact-info h3 {
            font-size: 2.5rem;
            margin-bottom: 1.5rem;
        }

        .contact-info p {
            color: var(--color-muted);
            margin-bottom: 2.5rem;
        }

        .contact-details {
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
            color: var(--color-muted);
            font-size: 0.95rem;
        }

        .contact-details strong {
            color: var(--color-ivory);
            display: block;
            margin-bottom: 0.25rem;
            text-transform: uppercase;
            font-size: 0.75rem;
            letter-spacing: 0.15em;
            color: var(--gold);
        }

        .contact-form {
            background: var(--bg-deep);
            border: 1px solid var(--border-gold);
            padding: 3rem;
        }

        .form-group {
            margin-bottom: 1.5rem;
        }

        .form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1.5rem;
        }

        @media (max-width: 600px) {
            .form-row {
                grid-template-columns: 1fr;
            }
        }

        .form-group label {
            display: block;
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.15em;
            color: var(--gold);
            margin-bottom: 0.5rem;
        }

        .form-group input,
        .form-group select,
        .form-group textarea {
            width: 100%;
            background: var(--bg-surface);
            border: 1px solid var(--border-gold);
            color: var(--color-ivory);
            padding: 1rem;
            font-family: var(--font-sans);
            font-size: 0.95rem;
            outline: none;
            transition: var(--transition-smooth);
        }

        .form-group input:focus,
        .form-group select:focus,
        .form-group textarea:focus {
            border-color: var(--gold);
            box-shadow: 0 0 10px rgba(212, 175, 55, 0.2);
        }

        .form-group textarea {
            resize: vertical;
            height: 150px;
        }

        /* =================================================================
           11. PIED DE PAGE (FOOTER)
           ================================================================ */
        .footer {
            background-color: var(--bg-deep);
            border-top: 1px solid var(--border-gold);
            padding: 5rem 0 2rem 0;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)) 2fr;
            gap: 3rem;
            margin-bottom: 4rem;
        }

        @media (max-width: 900px) {
            .footer-grid {
                grid-template-columns: 1fr;
            }
        }

        .footer-col h5 {
            font-size: 1rem;
            text-transform: uppercase;
            letter-spacing: 0.2em;
            color: var(--gold);
            margin-bottom: 1.5rem;
        }

        .footer-col ul {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
        }

        .footer-col a {
            color: var(--color-muted);
            text-decoration: none;
            font-size: 0.9rem;
            transition: var(--transition-smooth);
        }

        .footer-col a:hover {
            color: var(--gold);
        }

        .footer-bottom {
            border-top: 1px solid rgba(255,255,255,0.05);
            padding-top: 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 1rem;
            color: var(--color-muted);
            font-size: 0.85rem;
        }

        .social-links {
            display: flex;
            gap: 1.5rem;
        }

        /* =================================================================
           12. RESPONSIVE DESIGN (MEDIA QUERIES)
           ================================================================ */
        @media (max-width: 900px) {
            .menu-toggle {
                display: block;
            }

            .nav-menu {
                position: fixed;
                top: 90px;
                left: -100%;
                width: 100%;
                height: calc(100vh - 90px);
                background-color: var(--bg-deep);
                flex-direction: column;
                justify-content: center;
                align-items: center;
                transition: var(--transition-smooth);
                border-top: 1px solid var(--border-gold);
            }

            /* Ouverture du menu burger sans JS via un input checkbox fictif ou état (simulé via hover/focus ou ancres, ici adapté en CSS pur state) */
            /* Note : Sur mobile, sans JS, le menu s'active si l'on clique sur le label, 
               pour une robustesse maximale sans JS, on utilise un hack d'état ou affichage standard */
        }

        /* Animation de réduction de mouvement si requis */
        @media (prefers-reduced-motion: reduce) {
            html {
                scroll-behavior: auto;
            }
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.01ms !important;
            }
        }
    </style>
</head>
<body>

    <!-- =================================================================
       EN-TÊTE
       ================================================================ -->
    <header class="header">
        <div class="nav-container">
            <a href="#accueil" class="logo">
                Maison Horizon
                <span>Voyages d'Exception</span>
            </a>

            <!-- Menu Burger (CSS pur) -->
            <input type="checkbox" id="menu-toggle" class="menu-toggle">
            <label for="menu-toggle" class="burger-label" aria-label="Ouvrir le menu de navigation">
                <span></span>
                <span></span>
                <span></span>
            </label>

            <nav>
                <ul class="nav-menu">
                    <li><a href="#accueil" class="nav-link">Accueil</a></li>
                    <li><a href="#destinations" class="nav-link">Destinations</a></li>
                    <li><a href="#offres" class="nav-link">Offres</a></li>
                    <li><a href="#apropos" class="nav-link">À propos</a></li>
                    <li><a href="#contact" class="nav-link">Contact</a></li>
                </ul>
            </nav>
        </div>
    </header>

    <!-- =================================================================
       HERO
       ================================================================ -->
    <section id="accueil" class="hero">
        <div class="hero-content">
            <h1 class="hero-title">L'Art du Voyage <span class="gold-span">Sur Mesure</span></h1>
            <p class="hero-subtitle">Vivez des expériences inoubliables dans les endroits les plus exclusifs et préservés de la planète.</p>
            <div class="hero-buttons">
                <a href="#destinations" class="btn btn-gold">Explorer les destinations</a>
                <a href="#contact" class="btn">Contactez un concierge</a>
            </div>
        </div>
    </section>

    <!-- Barre de recherche visuelle -->
    <div class="search-bar-container">
        <form class="search-form" onsubmit="return false;">
            <div class="search-group">
                <label for="search-dest">Destination</label>
                <select id="search-dest">
                    <option value="">Toutes les destinations</option>
                    <option value="kyoto">Kyoto, Japon</option>
                    <option value="amalfitaine">Côte Amalfitaine</option>
                    <option value="patagonie">Patagonie</option>
                    <option value="maldives">Maldives</option>
                </select>
            </div>
            <div class="search-group">
                <label for="search-date">Date de départ</label>
                <input type="date" id="search-date">
            </div>
            <div class="search-group">
                <label for="search-travelers">Voyageurs</label>
                <select id="search-travelers">
                    <option value="1">1 Voyageur</option>
                    <option value="2" selected>2 Voyageurs</option>
                    <option value="3">3-4 Voyageurs</option>
                    <option value="5">VIP & Famille (5+)</option>
                </select>
            </div>
            <button type="submit" class="btn btn-gold" style="padding: 0.8rem 1rem;">Rechercher</button>
        </form>
    </div>

    <!-- =================================================================
       DESTINATIONS (Avec filtres CSS pur par radio buttons)
       ================================================================ -->
    <section id="destinations" class="destinations-section container">
        <p class="section-title">Évadez-vous</p>
        <h2 class="section-heading">Nos Destinations d'<span class="gold-span">Exception</span></h2>

        <!-- Conteneur des radios de filtrage CSS -->
        <input type="radio" name="filter" id="filter-all" checked>
        <input type="radio" name="filter" id="filter-europe">
        <input type="radio" name="filter" id="filter-asia">
        <input type="radio" name="filter" id="filter-americas">

        <div class="filters">
            <label for="filter-all" class="filter-btn">Toutes</label>
            <label for="filter-europe" class="filter-btn">Europe</label>
            <label for="filter-asia" class="filter-btn">Asie & Océanie</label>
            <label for="filter-americas" class="filter-btn">Amériques</label>
        </div>

        <div class="destinations-grid">
            <!-- 1. Europe -->
            <article class="destination-card europe card">
                <div class="card-img-wrapper">
                    <!-- À remplacer par une vraie photo HD de la Côte Amalfitaine -->
                    <img src="https://picsum.photos/seed/amalfitaine/800/600" alt="Vue panoramique de la Côte Amalfitaine" width="800" height="600" loading="lazy">
                </div>
                <div class="card-content">
                    <div>
                        <span class="card-location">Italie • Europe</span>
                        <h3 class="card-title">Côte Amalfitaine</h3>
                    </div>
                    <div class="card-footer">
                        <div class="card-price">À partir de <span>4 500 €</span></div>
                        <a href="#contact" class="nav-link" style="font-size: 0.75rem;">Découvrir →</a>
                    </div>
                </div>
            </article>

            <!-- 2. Asie -->
            <article class="destination-card asia card">
                <div class="card-img-wrapper">
                    <!-- À remplacer par une vraie photo HD de Kyoto -->
                    <img src="https://picsum.photos/seed/kyoto/800/600" alt="Jardin traditionnel japonais à Kyoto" width="800" height="600" loading="lazy">
                </div>
                <div class="card-content">
                    <div>
                        <span class="card-location">Japon • Asie</span>
                        <h3 class="card-title">Kyoto & Ses Ryokans</h3>
                    </div>
                    <div class="card-footer">
                        <div class="card-price">À partir de <span>6 200 €</span></div>
                        <a href="#contact" class="nav-link" style="font-size: 0.75rem;">Découvrir →</a>
                    </div>
                </div>
            </article>

            <!-- 3. Amériques -->
            <article class="destination-card americas card">
                <div class="card-img-wrapper">
                    <!-- À remplacer par une vraie photo HD de Patagonie -->
                    <img src="https://picsum.photos/seed/patagonie/800/600" alt="Paysage montagneux de la Patagonie" width="800" height="600" loading="lazy">
                </div>
                <div class="card-content">
                    <div>
                        <span class="card-location">Chili • Amériques</span>
                        <h3 class="card-title">Patagonie Sauvage</h3>
                    </div>
                    <div class="card-footer">
                        <div class="card-price">À partir de <span>8 900 €</span></div>
                        <a href="#contact" class="nav-link" style="font-size: 0.75rem;">Découvrir →</a>
                    </div>
                </div>
            </article>

            <!-- 4. Asie -->
            <article class="destination-card asia card">
                <div class="card-img-wrapper">
                    <!-- À remplacer par une vraie photo HD des Maldives -->
                    <img src="https://picsum.photos/seed/maldives/800/600" alt="Bungalows sur l'eau aux Maldives" width="800" height="600" loading="lazy">
                </div>
                <div class="card-content">
