<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Developer Agent - Calculatrice Simple</title>
    <style>
        /* --- Styles UI Basiques mais Modernes --- */
