```javascript
// État global de la calculatrice
const calculatorState = {
    displayValue: '0',
    firstOperand: null,
    waitingForSecondOperand: false,
    operator: null,
};

// Sélection des éléments de la vue
const screen = document.getElementById('calculator-screen');

function updateDisplay() {
    screen.textContent = calculatorState.displayValue;
}

updateDisplay();

// Gestion de la saisie des chiffres
function inputDigit(digit) {
    const { displayValue, waitingForSecondOperand } = calculatorState;

    if (waitingForSecondOperand === true) {
        calculatorState.displayValue = digit;
        calculatorState.waitingForSecondOperand = false;
    } else {
        calculatorState.displayValue = displayValue === '0' ? digit : displayValue + digit;
    }
}

// Gestion du point décimal
function inputDecimal(dot) {
    if (calculatorState.waitingForSecondOperand === true) return;

    if (!calculatorState.displayValue.includes(dot)) {
        calculatorState.displayValue += dot;
    }
}

// Gestion du changement de signe (+/-)
function toggleSign() {
    let value = parseFloat(calculatorState.displayValue);
    value = value * -1;
    calculatorState.displayValue = value.toString();
}

// Gestion du pourcentage (%)
function percentage() {
    let value = parseFloat(calculatorState.displayValue);
    value = value / 100;
    calculatorState.displayValue = value.toString();
}

// Gestion des opérateurs (+, -, *, /)
function handleOperator(nextOperator) {
    const { firstOperand, displayValue, operator } = calculatorState;
    const inputValue = parseFloat(displayValue);

    if (operator && calculatorState.waitingForSecondOperand) {
        calculatorState.operator = nextOperator;
        return;
    }

    if (firstOperand === null && !isNaN(inputValue)) {
        calculatorState.firstOperand = inputValue;
    } else if (operator) {
        const result = calculate(firstOperand, inputValue, operator);
        calculatorState.displayValue = `${parseFloat(result.toFixed(7))}`;
        calculatorState.firstOperand = result;
    }

    calculatorState.waitingForSecondOperand = true;
    calculatorState.operator = nextOperator;
}

// Fonction de calcul mathématique pur
function calculate(first, second, operator) {
    if (operator === 'add') return first + second;
    if (operator === 'subtract') return first - second;
    if (operator === 'multiply') return first * second;
    if (operator === 'divide') {
        if (second === 0) return 'Erreur';
        return first / second;
    }
    return second;
}

// Remise à zéro (AC)
function resetCalculator() {
    calculatorState.displayValue = '0';
    calculatorState.firstOperand = null;
    calculatorState.waitingForSecondOperand = false;
    calculatorState.operator = null;
}

// Écouteur d'événements sur le pavé tactile
const keys = document.querySelector('.calculator-keys');
keys.addEventListener('click', (event) => {
    const { target } = event;
    if (!target.matches('button')) return;

    if (target.classList.contains('key-number')) {
        if (target.dataset.action === 'decimal') {
            inputDecimal(target.textContent);
        } else {
            inputDigit(target.dataset.number);
        }
        updateDisplay();
        return;
    }

    if (target.classList.contains('key-operator')) {
        handleOperator(target.dataset.action);
        updateDisplay();
        return;
    }

    const action = target.dataset.action;

    if (action === 'clear') {
        resetCalculator();
        updateDisplay();
        return;
    }

    if (action === 'sign') {
        toggleSign();
        updateDisplay();
        return;
    }

    if (action === 'percent') {
        percentage();
        updateDisplay();
        return;
    }

    if (action === 'calculate') {
        handleOperator(calculatorState.operator);
        calculatorState.operator = null;
        updateDisplay();
        return;
    }
});

// Support du clavier physique pour un meilleur confort utilisateur
window.addEventListener('keydown', (e) => {
    if (!isNaN(e.key)) {
        inputDigit(e.key);
    } else if (e.key === '.') {
        inputDecimal('.');
    } else if (e.key === '+') {
        handleOperator('add');
    } else if (e.key === '-') {
        handleOperator('subtract');
    } else if (e.key === '*') {
        handleOperator('multiply');
    } else if (e.key === '/') {
        handleOperator('divide');
    } else if (e.key === 'Enter' || e.key === '=') {
        handleOperator(calculatorState.operator);
        calculatorState.operator = null;
    } else if (e.key === 'Escape' || e.key === 'c' || e.key === 'C') {
        resetCalculator();
    }
    updateDisplay();
});
```

