#### `map.js` (Carte Interactive avec Leaflet et LocalStorage)
```javascript
const mapData = [
    { id: 1, title: "Mitigé - Minigun Caché", type: "weapon", lat: 40, lng: -70, desc: "Sur le toit de l'hôtel tropical au nord." },
    { id: 2, title: "Easter Egg - Allusion à Tommy Vercetti", type: "easteregg", lat: 25, lng: -40, desc: "Chemise hawaïenne encadrée dans un bar secret." },
    { id: 3, title: "SuperSportive Sabre Turbo Custom", type: "vehicle", lat: -20, lng: -60, desc: "Garée dans une ruelle sombre du port." },
    { id: 4, title: "Lance-roquettes de rue", type: "weapon", lat: 10, lng: 30, desc: "Derrière les bennes à ordures du club de strip-tease." },
    { id: 5, title: "Deluxo Volante (Prototype)", type: "vehicle", lat: -40, lng: 50, desc: "Cachée dans un hangar désaffecté près de l'aéroport." }
];

let map;
let markersLayer;
let activeMapFilter = "all";

function initInteractiveMap() {
    // Initialisation de la carte Leaflet en mode CRS.Simple pour une image / plan personnalisé
    map = L.map('interactive-map', {
        crs: L.CRS.Simple,
        minZoom: -2,
        maxZoom: 2,
        zoomControl: false
    });

    // Utilisation d'une grille personnalisée ou dimension fixe simulant Vice City
    const bounds = [[-100, -100], [100, 100]];

    // Fond stylisé néon pour la carte simulée
    L.rectangle(bounds, {color: "#01cdfe", weight: 1, fill: true, fillColor: "#050510", fillOpacity: 0.9}).addTo(map);
    map.fitBounds(bounds);

    markersLayer = L.layerGroup().addTo(map);
    renderMarkers();
    updateMapStats();

    // Gestion des boutons de filtre de la carte
    document.querySelectorAll(".filter-toggle").forEach(btn => {
        btn.addEventListener("click", (e) => {
            document.querySelectorAll(".filter-toggle").forEach(b => b.classList.remove("active"));
            e.target.classList.add("active");
            activeMapFilter = e.target.getAttribute("data-filter");
            renderMarkers();
        });
    });
}

function renderMarkers() {
    markersLayer.clearLayers();

    const savedCollectibles = JSON.parse(localStorage.getItem("gta6_collectibles") || "[]");

    mapData.forEach(item => {
        if (activeMapFilter !== "all" && item.type !== activeMapFilter) return;

        const isCollected = savedCollectibles.includes(item.id);

        // Personnalisation des icônes selon le type
        let iconHtml = `<i class="fa-solid fa-map-pin" style="color: ${isCollected ? '#00ffcc' : '#ff71ce'}; font-size: 24px; text-shadow: 0 0 8px #ff71ce;"></i>`;

        const customIcon = L.divIcon({
            className: 'custom-map-icon',
            html: iconHtml,
            iconSize: [24, 24],
            iconAnchor: [12, 24]
        });

        const marker = L.marker([item.lat, item.lng], { icon: customIcon });

        marker.bindPopup(`
            <div style="font-family: 'Orbitron', sans-serif; color: #050510; min-width: 180px;">
                <h4 style="margin-bottom: 5px; color: #b967ff;">${item.title}</h4>
                <p style="font-size: 11px; margin-bottom: 8px; color: #333;">${item.desc}</p>
                <button onclick="toggleCollectible(${item.id})" style="background: #050510; color: #01cdfe; border: none; padding: 4px 8px; cursor: pointer; font-family: 'Orbitron'; font-size: 10px; width: 100%;">
                    ${isCollected ? 'Marquer comme Non Trouvé' : 'Marquer comme Trouvé ✔'}
                </button>
            </div>
        `);

        markersLayer.addLayer(marker);
    });
}

window.toggleCollectible = function(id) {
    let savedCollectibles = JSON.parse(localStorage.getItem("gta6_collectibles") || "[]");

    if (savedCollectibles.includes(id)) {
        savedCollectibles = savedCollectibles.filter(item => item !== id);
    } else {
        savedCollectibles.push(id);
    }

    localStorage.setItem("gta6_collectibles", JSON.stringify(savedCollectibles));
    renderMarkers();
    updateMapStats();
    map.closePopup();
};

function updateMapStats() {
    const savedCollectibles = JSON.parse(localStorage.getItem("gta6_collectibles") || "[]");
    const total = mapData.length;
    const found = savedCollectibles.length;

    document.getElementById("collectedCount").innerText = found;
    document.getElementById("totalCount").innerText = total;

    const percentage = (found / total) * 100;
    document.getElementById("progressFill").style.width = percentage + "%";
}
```

#### `app.js` (Routeur SPA & Initialisation Globale)
```javascript
document.addEventListener("DOMContentLoaded", () => {
    // Gestion du routage SPA (Changement de sections fluides)
    const navButtons = document.querySelectorAll(".nav-btn");
    const sections = document.querySelectorAll(".content-section");

    window.switchSection = function(targetId) {
        navButtons.forEach(btn => {
            if (btn.getAttribute("data-target") === targetId) {
                btn.classList.add("active");
            } else {
                btn.classList.remove("active");
            }
        });

        sections.forEach(section => {
            if (section.id === targetId) {
                section.classList.add("active");
                // Si on active la carte, rafraîchir la taille Leaflet pour éviter les bugs de rendu
                if (targetId === 'map' && window.mapInstance) {
                    setTimeout(() => window.mapInstance.invalidateSize(), 200);
                }
            } else {
                section.classList.remove("active");
            }
        });

        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    navButtons.forEach(button => {
        button.addEventListener("click", () => {
            const target = button.getAttribute("data-target");
            switchSection(target);
        });
    });

    // Initialisation des codes de triche
    renderCheats();

    const searchInput = document.getElementById("searchInput");
    const categoryFilter = document.getElementById("categoryFilter");

    searchInput.addEventListener("input", (e) => {
        renderCheats(categoryFilter.value, e.target.value);
    });

    categoryFilter.addEventListener("change", (e) => {
        renderCheats(e.target.value, searchInput.value);
    });

    // Initialisation de la carte interactive
    initInteractiveMap();
    window.mapInstance = map; // Stockage global pour l'ajustement de taille
});
