```javascript
document.addEventListener('DOMContentLoaded', () => {
    // --- 1. LOGIQUE DU SLIDER ---
    const sliderContainer = document.querySelector('.slider-container');
    const slides = document.querySelectorAll('.slide');
    const prevBtn = document.getElementById('prev-slide');
    const nextBtn = document.getElementById('next-slide');
    let currentSlide = 0;
    const totalSlides = slides.length;

    function updateSlider() {
        sliderContainer.style.transform = `translateX(-${currentSlide * 100}% )`;
    }

    function nextSlide() {
        currentSlide = (currentSlide + 1) % totalSlides;
        updateSlider();
    }

    function prevSlideFunc() {
        currentSlide = (currentSlide - 1 + totalSlides) % totalSlides;
        updateSlider();
    }

    nextBtn.addEventListener('click', nextSlide);
    prevBtn.addEventListener('click', prevSlideFunc);

    // Auto slide toutes les 5 secondes
    let slideInterval = setInterval(nextSlide, 5000);
    const heroSection = document.getElementById('slider-section');
    heroSection.addEventListener('mouseenter', () => clearInterval(slideInterval));
    heroSection.addEventListener('mouseleave', () => slideInterval = setInterval(nextSlide, 5000));

    // --- 2. LOGIQUE DE LA MAP INTERACTIVE (Pan, Zoom, Pins) ---
    const mapContainer = document.getElementById('map-container');
    const mapContent = document.getElementById('map-content');
    const mapTooltip = document.getElementById('map-tooltip');
    const tooltipTitle = document.getElementById('tooltip-title');
    const tooltipDesc = document.getElementById('tooltip-desc');
    const closeTooltip = document.getElementById('close-tooltip');
    const mapPins = document.querySelectorAll('.map-pin');

    let scale = 1;
    let pX = 0;
    let pY = 0;
    let isDragging = false;
    let startX, startY;

    mapContainer.addEventListener('mousedown', (e) => {
        isDragging = true;
        startX = e.clientX - pX;
        startY = e.clientY - pY;
    });

    window.addEventListener('mouseup', () => {
        isDragging = false;
    });

    mapContainer.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        pX = e.clientX - startX;
        pY = e.clientY - startY;
        updateMapTransform();
    });

    mapContainer.addEventListener('wheel', (e) => {
        e.preventDefault();
        const zoomIntensity = 0.1;
        if (e.deltaY < 0) {
            scale = Math.min(scale + zoomIntensity, 2.5);
        } else {
            scale = Math.max(scale - zoomIntensity, 1);
        }
        updateMapTransform();
    });

    function updateMapTransform() {
        mapContent.style.transform = `translate(${pX}px, ${pY}px) scale(${scale})`;
    }

    // Gestion des clics sur les Pins de la map
    mapPins.forEach(pin => {
        pin.addEventListener('click', (e) => {
            e.stopPropagation();
            const title = pin.getAttribute('data-title');
            const desc = pin.getAttribute('data-desc');
            tooltipTitle.textContent = title;
            tooltipDesc.textContent = desc;
            mapTooltip.classList.remove('hidden');
        });
    });

    closeTooltip.addEventListener('click', () => {
        mapTooltip.classList.add('hidden');
    });

    // --- 3. LOGIQUE DES CODES DE TRICHE ---
    const cheatsData = [
        { id: 1, title: "Invincibilité (God Mode)", category: "player", code: "PAIN-IS-NECESSARY", ps5: "R1, R2, L1, R2, Gauche", xbox: "RB, RT, LB, RT, Left", icon: "fa-shield-alt" },
        { id: 2, title: "Spawn Supercar (Cheetah)", category: "vehicles", code: "FAST-LANE-VC", ps5: "R1, Cercle, R2, Droite", xbox: "RB, B, RT, Right", icon: "fa-car-sport" },
        { id: 3, title: "Mode Ivrogne", category: "player", code: "LIQUID-COURAGE", ps5: "Triangle, Droite, Droite", xbox: "Y, Right, Right", icon: "fa-wine-bottle" },
        { id: 4, title: "Gravité Lunaire", category: "world", code: "SPACE-WALK", ps5: "Gauche, Gauche, L1", xbox: "Left, Left, LB", icon: "fa-moon" },
        { id: 5, title: "Spawn Hélicoptère Buzzard", category: "vehicles", code: "AIR-SUPPORT", ps5: "Cercle, Cercle, L1", xbox: "B, B, LB", icon: "fa-helicopter" },
        { id: 6, title: "Niveau de Recherche Max", category: "world", code: "WANTED-LEVEL-UP", ps5: "R1, R1, Cercle, R2", xbox: "RB, RB, B, RT", icon: "fa-star" }
    ];

    const cheatsGrid = document.getElementById('cheats-grid');
    const cheatSearch = document.getElementById('cheat-search');
    const filterBtns = document.querySelectorAll('.filter-btn');
    let currentCategory = 'all';

    function renderCheats(filter = '', category = 'all') {
        cheatsGrid.innerHTML = '';

        const filtered = cheatsData.filter(cheat => {
            const matchesSearch = cheat.title.toLowerCase().includes(filter.toLowerCase()) || cheat.code.toLowerCase().includes(filter.toLowerCase());
            const matchesCategory = category === 'all' || cheat.category === category;
            return matchesSearch && matchesCategory;
        });

        if (filtered.length === 0) {
            cheatsGrid.innerHTML = `<p class="text-gray-400 col-span-full text-center py-8">Aucun code de triche trouvé.</p>`;
            return;
        }

        filtered.forEach(cheat => {
            const card = document.createElement('div');
            card.className = "cheat-card p-5 rounded-xl flex flex-col justify-between";
            card.innerHTML = `
                <div>
                    <div class="flex items-center justify-between mb-3">
                        <span class="text-xs uppercase px-2 py-1 bg-white/5 rounded text-[#05d9e8] font-bold"><i class="fas ${cheat.icon} mr-1"></i> ${cheat.category}</span>
                        <span class="font-mono text-xs text-gray-400">#${cheat.id}</span>
                    </div>
                    <h3 class="text-white font-bold text-lg mb-2">${cheat.title}</h3>
                    <div class="bg-black/40 p-3 rounded-lg border border-white/5 mb-4">
                        <p class="text-xs text-gray-400 mb-1">Code Console :</p>
                        <p class="font-mono text-[#ff2a6d] font-bold text-sm tracking-wider">${cheat.code}</p>
                    </div>
                </div>
                <button onclick="copyToClipboard('${cheat.code}')" class="w-full bg-[#05d9e8]/10 hover:bg-[#05d9e8] text-[#05d9e8] hover:text-black font-bold py-2 rounded-lg text-xs transition-all flex items-center justify-center space-x-2 border border-[#05d9e8]/30">
                    <i class="fas fa-copy"></i> <span>COPIER LE CODE</span>
                </button>
            `;
            cheatsGrid.appendChild(card);
        });
    }

    // Gestion de la recherche
    cheatSearch.addEventListener('input', (e) => {
        renderCheats(e.target.value, currentCategory);
    });

    // Gestion des filtres par catégorie
    filterBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            filterBtns.forEach(b => {
                b.classList.remove('bg-[#ff2a6d]', 'text-black');
                b.classList.add('bg-[#1a102f]', 'text-gray-300');
            });
            btn.classList.remove('bg-[#1a102f]', 'text-gray-300');
            btn.classList.add('bg-[#ff2a6d]', 'text-black');

            currentCategory = btn.getAttribute('data-category');
            renderCheats(cheatSearch.value, currentCategory);
        });
    });

    // Initialisation affichage cheats
    renderCheats();
});

// Fonction globale pour copier dans le presse-papier
function copyToClipboard(text) {
    navigator.clipboard.writeText(text).then(() => {
        showToast(`Code "${text}" copié !`);
    });
}

function showToast(message) {
    let toast = document.getElementById('global-toast');
    if (!toast) {
        toast = document.createElement('div');
        toast.id = 'global-toast';
        toast.className = 'copy-toast';
        document.body.appendChild(toast);
    }
    toast.textContent = message;
    toast.classList.add('show');
    setTimeout(() => {
        toast.classList.remove('show');
    }, 2500);
}
