            flex-direction: column;
            align-items: center;
            text-align: center;
            padding: 60px 20px;
            background: radial-gradient(circle at center, rgba(121, 40, 202, 0.2) 0%, transparent 70%);
            border-radius: 20px;
            border: 1px solid rgba(255, 255, 255, 0.05);
            margin-bottom: 40px;
        }

