### 3. Fichier `script.js`
Gère la boucle de jeu, le moteur de projection 3D mathématique, les contrôles clavier/souris, la gestion des collisions et l'apparition des cibles.

```javascript
/**
 * Developer Agent - FPS Minimaliste Moteur 3D Pur JS
 */

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Éléments HUD
const scoreEl = document.getElementById('score');
const livesEl = document.getElementById('lives');
const ammoEl = document.getElementById('ammo');
const gameOverScreen = document.getElementById('game-over');
const finalScoreEl = document.getElementById('final-score');
const restartBtn = document.getElementById('restart-btn');

// Configuration de la taille du canvas
function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

// État du Jeu
let gameRunning = true;
let score = 0;
let lives = 3;
let maxAmmo = 10;
let ammo = maxAmmo;
let isReloading = false;

// Caméra et Joueur
const player = {
    x: 0,
    y: 0,
    z: 0,
    angle: 0, // Rotation horizontale en radians
    pitch: 0, // Regard haut/bas
    speed: 0.1
};

// Entrées Clavier
const keys = {
    z: false, s: false, q: false, d: false,
    ArrowUp: false, ArrowDown: false, ArrowLeft: false, ArrowRight: false,
    r: false
};

// Cibles 3D dans l'espace
let targets = [];
const maxTargets = 7;

class Target {
    constructor() {
        this.reset();
    }

    reset() {
        // Position aléatoire autour du joueur
        this.x = (Math.random() - 0.5) * 40;
        this.y = (Math.random() - 0.5) * 5 + 1; // Hauteur
        this.z = Math.random() * 35 + 5;        // Profondeur devant le joueur
        this.radius = 1.2;                      // Taille de la cible
        this.color = `hsl(${Math.random() * 360}, 100%, 50%)`;
    }

    update() {
        // Optionnel : faire avancer lentement les cibles vers le joueur
        this.z -= 0.03;
        if (this.z < 1) {
            // Si la cible atteint le joueur
            lives--;
            updateHUD();
            if (lives <= 0) {
                endGame();
            }
            this.reset();
        }
    }
}

// Initialisation des cibles
function initTargets() {
    targets = [];
    for (let i = 0; i < maxTargets; i++) {
        targets.push(new Target());
    }
}

// Écouteurs d'événements Clavier
window.addEventListener('keydown', (e) => {
    const key = e.key.toLowerCase();
    if (keys.hasOwnProperty(key)) keys[key] = true;
    if (keys.hasOwnProperty(e.key)) keys[e.key] = true;

    // Touche de rechargement
    if (key === 'r' && !isReloading) {
        reload();
    }
});

window.addEventListener('keyup', (e) => {
    const key = e.key.toLowerCase();
    if (keys.hasOwnProperty(key)) keys[key] = false;
    if (keys.hasOwnProperty(e.key)) keys[e.key] = false;
});

// Gestion de la Souris (Rotation de la caméra)
canvas.addEventListener('click', () => {
    canvas.requestPointerLock();
});

document.addEventListener('mousemove', (e) => {
    if (document.pointerLockElement === canvas && gameRunning) {
        const sensitivity = 0.003;
        player.angle -= e.movementX * sensitivity;
        player.pitch -= e.movementY * sensitivity;

        // Limiter le regard vertical
        if (player.pitch > 1.2) player.pitch = 1.2;
        if (player.pitch < -1.2) player.pitch = -1.2;
    }
});

// Mécanique de Tir (Clic Gauche)
window.addEventListener('mousedown', (e) => {
    if (e.button === 0 && document.pointerLockElement === canvas && gameRunning) {
        shoot();
    }
});

function shoot() {
    if (isReloading || ammo <= 0) return;

    ammo--;
    updateHUD();

    // Vérification de l'impact au centre de l'écran (Hitscan simplifié)
    // On trie les cibles de la plus proche à la plus lointaine
    let hitTarget = null;
    let closestDist = Infinity;

    for (let target of targets) {
        // Transformation de la cible dans le repère caméra
        let dx = target.x - player.x;
        let dz = target.z - player.z;

        // Rotation inverse selon l'angle de la caméra
        let cos = Math.cos(-player.angle);
        let sin = Math.sin(-player.angle);
        let tx = dx * cos - dz * sin;
        let tz = dx * sin + dz * cos;

        // Si la cible est devant nous
        if (tz > 0) {
            // Projection sur l'écran
            let fov = canvas.height;
            let screenX = (canvas.width / 2) + (tx / tz) * fov;
            let screenY = (canvas.height / 2) - (target.y - player.y - player.pitch * 200) / tz * fov; // Approximation du pitch

            // Calculer la distance radiale par rapport au centre de l'écran (réticule)
            let crosshairX = canvas.width / 2;
            let crosshairY = canvas.height / 2;
            let distToCrosshair = Math.hypot(screenX - crosshairX, screenY - crosshairY);

            // Taille apparente de la cible sur l'écran
            let radiusOnScreen = (target.radius / tz) * fov;

            if (distToCrosshair < radiusOnScreen && tz < closestDist) {
                closestDist = tz;
                hitTarget = target;
            }
        }
    }

    if (hitTarget) {
        score += 100;
        hitTarget.reset();
        updateHUD();
    }
}

function reload() {
    if (ammo === maxAmmo) return;
    isReloading = true;
    ammoEl.innerText = "RECHARGE...";
    setTimeout(() => {
        if (!gameRunning) return;
        ammo = maxAmmo;
        isReloading = false;
        updateHUD();
    }, 1000);
}

function updateHUD() {
    scoreEl.innerText = score;
    livesEl.innerText = lives;
    if (!isReloading) {
        ammoEl.innerText = `${ammo} / ${maxAmmo}`;
    }
}

// Mouvement du Joueur
function updatePlayer() {
    let moveSpeed = player.speed;
    let forward = (keys.z || keys.ArrowUp) ? 1 : (keys.s || keys.ArrowDown) ? -1 : 0;
    let side = (keys.d || keys.ArrowRight) ? 1 : (keys.q || keys.ArrowLeft) ? -1 : 0;

    if (forward !== 0 || side !== 0) {
        let cos = Math.cos(player.angle);
        let sin = Math.sin(player.angle);

        // Calcul vectoriel des déplacements par rapport à l'orientation de la caméra
        player.x += (forward * sin + side * cos) * moveSpeed;
        player.z += (forward * cos - side * sin) * moveSpeed;
    }
}

// Boucle de Rendu 3D (Moteur Maison)
function render() {
    // Effacer le canvas avec un effet visuel de sol/ciel
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Dessiner un sol minimaliste
    ctx.fillStyle = '#0a0a14';
    ctx.fillRect(0, canvas.height / 2, canvas.width, canvas.height / 2);

    // Mettre à jour les cibles et les trier par profondeur (peintre algorithm)
    targets.forEach(t => t.update());

    // Trier de la plus loin à la plus proche pour l'affichage correct
    let sortedTargets = [...targets].sort((a, b) => {
        let distA = Math.hypot(a.x - player.x, a.z - player.z);
        let distB = Math.hypot(b.x - player.x, b.z - player.z);
        return distB - distA;
    });

    // Rendu des cibles 3D
    for (let target of sortedTargets) {
        let dx = target.x - player.x;
        let dz = target.z - player.z;

        // Rotation caméra
        let cos = Math.cos(-player.angle);
        let sin = Math.sin(-player.angle);
        let tx = dx * cos - dz * sin;
        let tz = dx * sin + dz * cos;

        // Ne dessiner que si la cible est devant la caméra
        if (tz > 0.2) {
            let fov = canvas.height;
            let screenX = (canvas.width / 2) + (tx / tz) * fov;
            // Intégration du pitch de la caméra pour regarder haut/bas
            let screenY = (canvas.height / 2) - ((target.y - player.y) / tz) * fov + (player.pitch * fov);
            let radiusOnScreen = (target.radius / tz) * fov;

            // Dessin de la cible (Cercle avec effet néon)
            ctx.save();
            ctx.beginPath();
            ctx.arc(screenX, screenY, radiusOnScreen, 0, Math.PI * 2);
            ctx.fillStyle = target.color;
            ctx.shadowColor = target.color;
            ctx.shadowBlur = 15;
            ctx.fill();
            ctx.lineWidth = 3;
            ctx.strokeStyle = '#ffffff';
            ctx.stroke();
            ctx.restore();
        }
    }
}

// Boucle Principale du Jeu
function gameLoop() {
    if (!gameRunning) return;

    updatePlayer();
    render();

    requestAnimationFrame(gameLoop);
}

function endGame() {
    gameRunning = false;
    document.exitPointerLock();
    finalScoreEl.innerText = score;
    gameOverScreen.classList.remove('hidden');
}

// Redémarrage du jeu
restartBtn.addEventListener('click', () => {
    score = 0;
    lives = 3;
    ammo = maxAmmo;
    player.x = 0;
    player.z = 0;
    player.angle = 0;
    player.pitch = 0;
    gameRunning = true;
    gameOverScreen.classList.add('hidden');
    initTargets();
    updateHUD();
    gameLoop();
});

// Lancement initial
initTargets();
updateHUD();
gameLoop();
```

