    </main>

    <!-- Réticule de visée (Crosshair) -->
    <div class="crosshair"></div>

    <!-- Barre d'Action Fixe (HUD Inférieur / Arme) -->
    <footer class="hud-bottom">
        <div class="weapon">
            <!-- Arme stylisée en CSS pur -->
            <div class="gun-barrel"></div>
            <div class="gun-body"></div>
        </div>
        <div class="ammo">MUNITIONS: <span class="hud-value">∞</span></div>
    </footer>

</body>
</html>
```

